use trinity_macros::trinity_test;use trinityal::{PixelFormat,TextureType,Tr2BitmapDimensions};fn dimensions(t:TextureType,w:u32,h:u32,d:u32,m:u32)->Tr2BitmapDimensions{Tr2BitmapDimensions{texture_type:t,width:w,height:h,volume_depth:d,mip_count:m,..Default::default()}}
#[trinity_test(legacy="trinityal/tests/BitmapDimensions.cpp::BitmapDimensions::InitialSizeIsZero",verification="kani")]fn initial_size_is_zero(){let d=Tr2BitmapDimensions::default();assert_eq!(0,d.get_width());assert_eq!(0,d.get_true_mip_count());assert_eq!(PixelFormat::Unknown,d.get_format());assert_eq!(TextureType::Invalid,d.get_type());}
#[trinity_test(legacy="trinityal/tests/BitmapDimensions.cpp::BitmapDimensions::ReportsCorrect2DSizes",verification="kani")]fn reports_correct_2d_sizes(){let d=dimensions(TextureType::Texture2D,32,16,0,2);assert_eq!((32,16,0,2),(d.get_width(),d.get_height(),d.get_depth(),d.get_true_mip_count()));}
#[trinity_test(legacy="trinityal/tests/BitmapDimensions.cpp::BitmapDimensions::ReportsCorrect3DSizes",verification="kani")]fn reports_correct_3d_sizes(){let d=dimensions(TextureType::Texture3D,32,16,64,2);assert_eq!(64,d.get_depth());assert_eq!(2,d.get_true_mip_count());}
#[trinity_test(legacy="trinityal/tests/BitmapDimensions.cpp::BitmapDimensions::CalculatesTrueMipCountAndMipSizes",verification="kani")]fn calculates_true_mip_count_and_mip_sizes(){let d=dimensions(TextureType::Texture3D,32,16,64,0);assert_eq!(6,d.get_true_mip_count());assert_eq!((32,16,64),(d.get_mip_width(0),d.get_mip_height(0),d.get_mip_depth(0)));}
#[trinity_test(legacy="trinityal/tests/BitmapDimensions.cpp::BitmapDimensions::GettingMipSizesForIncorrectMipReturnsZero",verification="kani")]fn getting_mip_sizes_for_incorrect_mip_returns_zero(){let d=dimensions(TextureType::Texture3D,32,16,64,0);assert_eq!((0,0,0),(d.get_mip_width(10),d.get_mip_height(10),d.get_mip_depth(10)));}
#[trinity_test(legacy="trinityal/tests/BitmapDimensions.cpp::BitmapDimensions::CalculatesTrueMipCountAndMipSizesForNptTexture",verification="kani")]fn calculates_true_mip_count_for_npt_texture(){let d=dimensions(TextureType::Texture2D,731,317,0,0);assert_eq!(10,d.get_true_mip_count());assert_eq!(365,d.get_mip_width(1));}
#[trinity_test(legacy="trinityal/tests/BitmapDimensions.cpp::BitmapDimensions::CalculatesCorrectMipSize",verification="kani")]fn calculates_correct_mip_size(){let mut d=dimensions(TextureType::Texture2D,32,16,0,0);d.format=PixelFormat::B8G8R8A8Unorm;assert_eq!(2048,d.get_mip_size(0));d.format=PixelFormat::Bc1Unorm;assert_eq!(256,d.get_mip_size(0));}
